SELECT COUNT(*) AS total_trip_count
FROM fct_trips
WHERE EXTRACT(YEAR FROM pickup_at) = 2023;

SELECT AVG(trip_distance_miles) AS avg_trip_distance
FROM fct_trips
WHERE EXTRACT(YEAR FROM pickup_at) = 2023;

SELECT AVG(trip_duration_minutes) AS avg_trip_duration_minutes
FROM fct_trips
WHERE EXTRACT(YEAR FROM pickup_at) = 2023;

SELECT SUM(tip_amount) AS total_tips
FROM fct_trips
WHERE payment_type = 'Credit card';

SELECT SUM(tolls_amount) AS total_tolls
FROM fct_trips
WHERE EXTRACT(YEAR FROM pickup_at) = 2023;

SELECT MAX(trip_distance_miles) AS max_trip_distance
FROM fct_trips
WHERE pickup_date >= '2023-01-01' AND pickup_date < '2024-01-01';

SELECT SUM(trip_distance_miles) AS total_miles
FROM fct_trips
WHERE fare_amount > 0 AND trip_distance_miles > 0;

SELECT COUNT(*) AS cash_trips
FROM fct_trips
WHERE payment_type = 'Cash';

SELECT COUNT(*) AS trip_count
FROM fct_trips
WHERE payment_type = 'Credit card';

SELECT COUNT(*) AS trip_count
FROM fct_trips
WHERE pickup_borough = 'Manhattan' AND pickup_date >= '2023-01-01' AND pickup_date < '2024-01-01';

SELECT COUNT(*) AS trip_count
FROM fct_trips
WHERE pickup_borough = 'Queens' AND pickup_date >= '2023-01-01' AND pickup_date < '2024-01-01';

SELECT COUNT(*) AS trip_count
FROM fct_trips
WHERE pickup_date >= '2023-01-01' AND pickup_date < '2023-02-01';

SELECT COUNT(*) AS trip_count
FROM fct_trips
WHERE pickup_date >= '2023-07-01' AND pickup_date < '2023-08-01';

SELECT AVG(fare_amount) AS avg_fare
FROM fct_trips
WHERE month_key = '2023-03';

SELECT COUNT(*) AS trip_count
FROM fct_trips
WHERE is_weekend = TRUE;

SELECT COUNT(*) AS trip_count
FROM fct_trips
WHERE passenger_count = 1;

SELECT COUNT(*) AS trip_count
FROM fct_trips
WHERE passenger_count > 4;

SELECT COUNT(*) AS trip_count
FROM fct_trips
WHERE trip_distance_miles > 10;

SELECT COUNT(*) AS trip_count
FROM fct_trips
WHERE trip_distance_miles < 1;

SELECT COUNT(*) AS trip_count
FROM fct_trips
WHERE trip_duration_minutes > 60;

SELECT COUNT(*) AS trip_count
FROM fct_trips
WHERE fare_amount > 100;

SELECT COUNT(*) AS trip_count
FROM fct_trips
WHERE rate_code = 'JFK' AND EXTRACT(YEAR FROM pickup_at) = 2023;

SELECT COUNT(*) AS trip_count
FROM fct_trips
WHERE tip_amount > 0;

SELECT AVG(fare_amount) AS avg_cash_fare
FROM fct_trips
WHERE payment_type = 'Cash';

SELECT AVG(tip_amount) AS avg_tip
FROM fct_trips
WHERE payment_type = 'Credit card';

SELECT COUNT(*) AS trip_count
FROM fct_trips
WHERE pickup_date = '2023-12-31';

SELECT COUNT(*) AS trip_count
FROM fct_trips
WHERE pickup_date = '2023-07-04';

SELECT COUNT(*) AS trip_count
FROM fct_trips
WHERE pickup_hour = 0;

SELECT COUNT(*) AS trip_count
FROM fct_trips
WHERE pickup_hour = 8;

SELECT COUNT(*) AS dispute_trip_count
FROM fct_trips
WHERE payment_type = 'Dispute';

SELECT COUNT(*) AS trip_count
FROM fct_trips
WHERE payment_type = 'No charge';

SELECT MIN(fare_amount) AS lowest_fare
FROM fct_trips
WHERE YEAR(pickup_at) = 2023;

SELECT COUNT(DISTINCT pickup_zone_id) AS num_taxi_zones
FROM fct_trips
WHERE pickup_date >= '2023-01-01' AND pickup_date < '2024-01-01';

SELECT COUNT(*) AS trip_count
FROM fct_trips
WHERE trip_duration_minutes < 5;

SELECT COUNT(*) AS trip_count
FROM fct_trips
WHERE pickup_borough = 'Manhattan' AND dropoff_borough = 'Manhattan';

SELECT COUNT(*) AS trip_count
FROM fct_trips
WHERE pickup_date >= '2023-01-01' AND pickup_date < '2023-04-01';

SELECT SUM(total_amount) AS total_revenue
FROM fct_trips
WHERE month_key BETWEEN '2023-10' AND '2023-12';

SELECT AVG(fare_amount) AS avg_fare
FROM fct_trips
WHERE trip_distance_miles > 20;

SELECT AVG(trip_distance_miles / (trip_duration_minutes / 60)) AS avg_speed_mph
FROM fct_trips
WHERE pickup_date >= '2023-01-01' AND pickup_date <= '2023-12-31';

SELECT AVG(trip_distance_miles / (trip_duration_minutes / 60)) AS avg_speed_mph
FROM fct_trips
WHERE pickup_hour = 8 AND pickup_date BETWEEN '2023-01-01' AND '2023-12-31';

SELECT COUNT(*) AS trip_count
FROM fct_trips
WHERE pickup_date >= '2023-12-01' AND pickup_date < '2023-12-32' AND passenger_count >= 5;

SELECT AVG(total_amount) AS average_total_amount
FROM fct_trips
WHERE tolls_amount > 0;

SELECT COUNT(*) AS trip_count
FROM fct_trips
WHERE EXTRACT(MONTH FROM pickup_date) IN (6, 7, 8);

SELECT AVG(trip_duration_minutes) AS avg_trip_duration
FROM fct_trips
WHERE pickup_hour = 17 AND pickup_date >= '2023-01-01' AND pickup_date < '2024-01-01';

SELECT SUM(tip_amount) AS cash_tips
FROM fct_trips
WHERE payment_type = 'Cash';

SELECT COUNT(*) AS trip_count
FROM fct_trips
WHERE pickup_zone_id = dropoff_zone_id;

SELECT AVG(fare_amount) AS avg_fare
FROM fct_trips
WHERE rate_code = 'Standard rate';

SELECT COUNT(*) AS trip_count
FROM fct_trips
WHERE pickup_date BETWEEN '2023-12-25' AND '2023-12-31';

SELECT CAST(SUM(CASE WHEN pickup_borough = 'Manhattan' THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) AS percentage_of_trips_in_manhattan
FROM fct_trips
WHERE pickup_date >= '2023-01-01' AND pickup_date < '2024-01-01';

SELECT CAST(SUM(CASE WHEN is_weekend THEN 1 ELSE 0 END) AS REAL) * 100 / COUNT(*) AS weekend_percentage
FROM fct_trips
WHERE pickup_date >= '2023-01-01' AND pickup_date < '2024-01-01';

SELECT AVG(trip_count) AS avg_trips_per_day
FROM trips_hourly_demand
WHERE pickup_date >= '2023-01-01' AND pickup_date < '2024-01-01';

SELECT PERCENTILE_CONT(0.95) WITHIN GROUP (ORDER BY trip_duration_minutes) AS percentile_95th
FROM fct_trips
WHERE EXTRACT(YEAR FROM pickup_at) = 2023;

SELECT PERCENTILE_CONT(0.9) WITHIN GROUP (ORDER BY fare_amount) AS fare_amount_90th_percentile
FROM fct_trips
WHERE EXTRACT(YEAR FROM pickup_at) = 2023;

SELECT COUNT(*) AS trip_count
FROM fct_trips
WHERE fare_amount > (SELECT avg_fare FROM trips_hourly_demand);

SELECT AVG(tip_amount) AS avg_cash_tip
FROM fct_trips
WHERE payment_type = 'Cash';

SELECT AVG(trip_duration_minutes) AS average_wait_time
FROM fct_trips
WHERE pickup_date >= '2023-01-01' AND pickup_date < '2024-01-01';
